CREATE VIEW v91208 AS SELECT x20.v90797, COALESCE(x20.v90798, CAST(7 AS UNSIGNED)) AS x2, 'YYYYYYYYYYYYYYYYYYYY' AS x3, STATEMENT_DIGEST_TEXT('select 1, 2, 3') AS x4, COALESCE(x20.v90798, CAST('yet another binary data' AS BINARY)) AS x5, COALESCE(x20.v90797, CAST('5:4:3' AS TIME)) AS x6, COALESCE(x20.v90798, x20.v90798) AS x7, COALESCE(x20.v90797, x20.v90797) AS x8, ADDTIME(CAST('00:00:00.1' AS TIME), CAST('a' AS BINARY)) AS x9 FROM v90796 AS x20